// noda_dart: new code. The parts of .NET's CultureInfo, DateTimeFormatInfo, CompareInfo and IFormatProvider
// that NodaTime reads; the data is generated by tools/.

import 'package:meta/meta.dart';

import 'HostLanguages_stub.dart'
    if (dart.library.io) 'HostLanguages_io.dart'
    if (dart.library.js_interop) 'HostLanguages_web.dart';
import 'InvariantCultureData.generated.dart';
import 'NodaCultureInfo.dart' as nt show CompareInfo;
import 'PatternResources.generated.dart';

/// Culture data as written by tools/ (cultures): what [NodaCultureInfo.FromData] creates a culture from.
final class CultureData {
  /// The culture name (CultureInfo.Name), e.g. "es-ES"; "" for the invariant culture.
  final String Name;

  /// The culture's date and time formatting data (CultureInfo.DateTimeFormat).
  final DateTimeFormatData DateTimeFormat;

  /// NodaTime pattern resources that differ from the neutral ones (lib/src/Globalization/PatternResources.generated.dart).
  final Map<String, String>? PatternResources;

  const CultureData({required this.Name, required this.DateTimeFormat, this.PatternResources});

  /// A copy of this data with the given members replaced (e.g. a test culture with modified patterns).
  CultureData CopyWith({String? Name, DateTimeFormatData? DateTimeFormat, Map<String, String>? PatternResources}) =>
      CultureData(
          Name: Name ?? this.Name,
          DateTimeFormat: DateTimeFormat ?? this.DateTimeFormat,
          PatternResources: PatternResources ?? this.PatternResources);
}

/// The members of .NET's DateTimeFormatInfo that NodaTime uses.
class DateTimeFormatData {
  /// The .NET calendar type name, e.g. "GregorianCalendar".
  final String Calendar;

  /// The designator for hours before noon, e.g. "AM" (the `tt` pattern specifier).
  final String AMDesignator;

  /// The designator for hours after noon, e.g. "PM" (the `tt` pattern specifier).
  final String PMDesignator;

  /// The separator between hours, minutes and seconds (the `:` pattern specifier), e.g. ":".
  final String TimeSeparator;

  /// The separator between year, month and day (the `/` pattern specifier), e.g. "/".
  final String DateSeparator;

  /// The short date pattern (standard pattern `d`), e.g. "dd/MM/yyyy".
  final String ShortDatePattern;

  /// The long date pattern (standard pattern `D`), e.g. "dddd, d MMMM yyyy".
  final String LongDatePattern;

  /// The short time pattern (standard pattern `t`), e.g. "HH:mm".
  final String ShortTimePattern;

  /// The long time pattern (standard pattern `T`), e.g. "HH:mm:ss".
  final String LongTimePattern;

  /// The long date and long time pattern (standard pattern `F`), e.g. "dddd, d MMMM yyyy HH:mm:ss".
  final String FullDateTimePattern;

  /// The month and day pattern (.NET's `M` format), e.g. "d MMMM".
  final String MonthDayPattern;

  /// The year and month pattern (.NET's `Y` format), e.g. "MMMM yyyy".
  final String YearMonthPattern;

  /// The sortable (ISO 8601) date and time pattern (.NET's `s` format): "yyyy'-'MM'-'dd'T'HH':'mm':'ss".
  final String SortableDateTimePattern;

  /// The universal sortable date and time pattern (.NET's `u` format): "yyyy'-'MM'-'dd HH':'mm':'ss'Z'".
  final String UniversalSortableDateTimePattern;

  /// The RFC 1123 date and time pattern (.NET's `R` format): "ddd, dd MMM yyyy HH':'mm':'ss 'GMT'".
  final String RFC1123Pattern;

  /// The full month names (`MMMM`): 13 entries as in .NET (the 13th usually empty).
  final List<String> MonthNames;

  /// The abbreviated month names (the `MMM` pattern specifier, standalone): 13 entries, like [MonthNames].
  final List<String> AbbreviatedMonthNames;

  /// The full month names in the genitive case (`d MMMM`): 13 entries, like [MonthNames].
  final List<String> MonthGenitiveNames;

  /// The abbreviated month names in the genitive case (`d MMM`): 13 entries, like [MonthGenitiveNames].
  final List<String> AbbreviatedMonthGenitiveNames;

  /// The full day names (the `dddd` pattern specifier): 7 entries, Sunday first, as in .NET.
  final List<String> DayNames;

  /// The abbreviated day names (the `ddd` pattern specifier): 7 entries, Sunday first.
  final List<String> AbbreviatedDayNames;

  /// The shortest day names (e.g. "Su"): 7 entries, Sunday first.
  final List<String> ShortestDayNames;

  /// The full era names (the `gg` pattern specifier): GetEraName(1..n) of the culture's calendar.
  final List<String> EraNames;

  /// The abbreviated era names: GetAbbreviatedEraName(1..n) of the culture's calendar.
  final List<String> AbbreviatedEraNames;

  /// The first day of the week, as a System.DayOfWeek value (0 = Sunday).
  final int FirstDayOfWeek;

  /// How the first week of the year is chosen (a System.Globalization.CalendarWeekRule value).
  final int CalendarWeekRule;

  const DateTimeFormatData({
    required this.Calendar,
    required this.AMDesignator,
    required this.PMDesignator,
    required this.TimeSeparator,
    required this.DateSeparator,
    required this.ShortDatePattern,
    required this.LongDatePattern,
    required this.ShortTimePattern,
    required this.LongTimePattern,
    required this.FullDateTimePattern,
    required this.MonthDayPattern,
    required this.YearMonthPattern,
    required this.SortableDateTimePattern,
    required this.UniversalSortableDateTimePattern,
    required this.RFC1123Pattern,
    required this.MonthNames,
    required this.AbbreviatedMonthNames,
    required this.MonthGenitiveNames,
    required this.AbbreviatedMonthGenitiveNames,
    required this.DayNames,
    required this.AbbreviatedDayNames,
    required this.ShortestDayNames,
    required this.EraNames,
    required this.AbbreviatedEraNames,
    required this.FirstDayOfWeek,
    required this.CalendarWeekRule,
  });

  /// A copy of this data with the given members replaced.
  DateTimeFormatData CopyWith({
    String? Calendar,
    String? AMDesignator,
    String? PMDesignator,
    String? TimeSeparator,
    String? DateSeparator,
    String? ShortDatePattern,
    String? LongDatePattern,
    String? ShortTimePattern,
    String? LongTimePattern,
    String? FullDateTimePattern,
    String? MonthDayPattern,
    String? YearMonthPattern,
    String? SortableDateTimePattern,
    String? UniversalSortableDateTimePattern,
    String? RFC1123Pattern,
    List<String>? MonthNames,
    List<String>? AbbreviatedMonthNames,
    List<String>? MonthGenitiveNames,
    List<String>? AbbreviatedMonthGenitiveNames,
    List<String>? DayNames,
    List<String>? AbbreviatedDayNames,
    List<String>? ShortestDayNames,
    List<String>? EraNames,
    List<String>? AbbreviatedEraNames,
    int? FirstDayOfWeek,
    int? CalendarWeekRule,
  }) =>
      DateTimeFormatData(
        Calendar: Calendar ?? this.Calendar,
        AMDesignator: AMDesignator ?? this.AMDesignator,
        PMDesignator: PMDesignator ?? this.PMDesignator,
        TimeSeparator: TimeSeparator ?? this.TimeSeparator,
        DateSeparator: DateSeparator ?? this.DateSeparator,
        ShortDatePattern: ShortDatePattern ?? this.ShortDatePattern,
        LongDatePattern: LongDatePattern ?? this.LongDatePattern,
        ShortTimePattern: ShortTimePattern ?? this.ShortTimePattern,
        LongTimePattern: LongTimePattern ?? this.LongTimePattern,
        FullDateTimePattern: FullDateTimePattern ?? this.FullDateTimePattern,
        MonthDayPattern: MonthDayPattern ?? this.MonthDayPattern,
        YearMonthPattern: YearMonthPattern ?? this.YearMonthPattern,
        SortableDateTimePattern: SortableDateTimePattern ?? this.SortableDateTimePattern,
        UniversalSortableDateTimePattern: UniversalSortableDateTimePattern ?? this.UniversalSortableDateTimePattern,
        RFC1123Pattern: RFC1123Pattern ?? this.RFC1123Pattern,
        MonthNames: MonthNames ?? this.MonthNames,
        AbbreviatedMonthNames: AbbreviatedMonthNames ?? this.AbbreviatedMonthNames,
        MonthGenitiveNames: MonthGenitiveNames ?? this.MonthGenitiveNames,
        AbbreviatedMonthGenitiveNames: AbbreviatedMonthGenitiveNames ?? this.AbbreviatedMonthGenitiveNames,
        DayNames: DayNames ?? this.DayNames,
        AbbreviatedDayNames: AbbreviatedDayNames ?? this.AbbreviatedDayNames,
        ShortestDayNames: ShortestDayNames ?? this.ShortestDayNames,
        EraNames: EraNames ?? this.EraNames,
        AbbreviatedEraNames: AbbreviatedEraNames ?? this.AbbreviatedEraNames,
        FirstDayOfWeek: FirstDayOfWeek ?? this.FirstDayOfWeek,
        CalendarWeekRule: CalendarWeekRule ?? this.CalendarWeekRule,
      );
}

/// Equivalent of System.IFormatProvider: a [NodaCultureInfo] or a [DateTimeFormatInfo].
abstract interface class IFormatProvider {}

/// Equivalent of System.Globalization.CompareOptions (the values NodaTime uses).
extension type const CompareOptions(int value) implements Object {
  static const CompareOptions None = CompareOptions(0);
  static const CompareOptions IgnoreCase = CompareOptions(1);
  static const CompareOptions Ordinal = CompareOptions(0x40000000);
  static const CompareOptions OrdinalIgnoreCase = CompareOptions(0x10000000);
}

/// Equivalent of System.Globalization.DateTimeFormatInfo: read-only culture formatting data.
final class DateTimeFormatInfo extends DateTimeFormatData implements IFormatProvider {
  /// Creates the format info for [data] (its lists are copied, read-only).
  DateTimeFormatInfo(DateTimeFormatData data)
      : super(
          Calendar: data.Calendar,
          AMDesignator: data.AMDesignator,
          PMDesignator: data.PMDesignator,
          TimeSeparator: data.TimeSeparator,
          DateSeparator: data.DateSeparator,
          ShortDatePattern: data.ShortDatePattern,
          LongDatePattern: data.LongDatePattern,
          ShortTimePattern: data.ShortTimePattern,
          LongTimePattern: data.LongTimePattern,
          FullDateTimePattern: data.FullDateTimePattern,
          MonthDayPattern: data.MonthDayPattern,
          YearMonthPattern: data.YearMonthPattern,
          SortableDateTimePattern: data.SortableDateTimePattern,
          UniversalSortableDateTimePattern: data.UniversalSortableDateTimePattern,
          RFC1123Pattern: data.RFC1123Pattern,
          MonthNames: List.unmodifiable(data.MonthNames),
          AbbreviatedMonthNames: List.unmodifiable(data.AbbreviatedMonthNames),
          MonthGenitiveNames: List.unmodifiable(data.MonthGenitiveNames),
          AbbreviatedMonthGenitiveNames: List.unmodifiable(data.AbbreviatedMonthGenitiveNames),
          DayNames: List.unmodifiable(data.DayNames),
          AbbreviatedDayNames: List.unmodifiable(data.AbbreviatedDayNames),
          ShortestDayNames: List.unmodifiable(data.ShortestDayNames),
          EraNames: List.unmodifiable(data.EraNames),
          AbbreviatedEraNames: List.unmodifiable(data.AbbreviatedEraNames),
          FirstDayOfWeek: data.FirstDayOfWeek,
          CalendarWeekRule: data.CalendarWeekRule,
        );

  /// Equivalent of DateTimeFormatInfo.GetEraName(int).
  String GetEraName(int era) => era >= 1 && era <= EraNames.length ? EraNames[era - 1] : '';

  /// Equivalent of DateTimeFormatInfo.GetAbbreviatedEraName(int).
  String GetAbbreviatedEraName(int era) =>
      era >= 1 && era <= AbbreviatedEraNames.length ? AbbreviatedEraNames[era - 1] : '';

  /// The invariant culture's format info.
  static DateTimeFormatInfo get InvariantInfo => NodaCultureInfo.InvariantCulture.DateTimeFormat;
}

/// Equivalent of System.Globalization.CompareInfo, for the name matching of NodaTime's parsers.
///
/// Matches .NET's ICU collation for that text on every platform: [CompareOptions.IgnoreCase] ignores case (Turkish
/// i included) and default-ignorable characters; other options compare ordinally.
final class CompareInfo {
  /// The culture name, e.g. "tr-TR"; "" for the invariant culture.
  final String Name;

  // Whether the culture's language has the Turkish case mappings for i (tr, az).
  final bool _turkicCasing;

  @internal
  CompareInfo.NewName(this.Name) : _turkicCasing = _IsTurkic(Name);

  static bool _IsTurkic(String name) {
    final language = name.split('-').first.toLowerCase();
    return language == 'tr' || language == 'az';
  }

  /// Equivalent of CompareInfo.Compare(string1, string2, options).
  int Compare(String string1, String string2, [CompareOptions options = CompareOptions.None]) =>
      CompareSubstrings(string1, 0, string1.length, string2, 0, string2.length, options);

  /// Equivalent of CompareInfo.Compare(string1, offset1, length1, string2, offset2, length2, options).
  int CompareSubstrings(String string1, int offset1, int length1, String string2, int offset2, int length2,
      [CompareOptions options = CompareOptions.None]) {
    String a = string1.substring(offset1, offset1 + length1);
    String b = string2.substring(offset2, offset2 + length2);
    switch (options) {
      case CompareOptions.Ordinal:
        return a.compareTo(b).sign;
      case CompareOptions.OrdinalIgnoreCase:
        return a.toUpperCase().compareTo(b.toUpperCase()).sign;
      case CompareOptions.IgnoreCase:
        return a == b ? 0 : _FoldCase(a).compareTo(_FoldCase(b)).sign;
      default:
        return a == b ? 0 : _RemoveIgnorable(a).compareTo(_RemoveIgnorable(b)).sign;
    }
  }

  /// Equivalent of CompareInfo.IsPrefix(source, prefix, options).
  bool IsPrefix(String source, String prefix, [CompareOptions options = CompareOptions.None]) =>
      prefix.length <= source.length &&
      CompareSubstrings(source, 0, prefix.length, prefix, 0, prefix.length, options) == 0;

  /// The text with case folded (to upper case, code point by code point) and default-ignorable characters removed.
  String _FoldCase(String text) {
    final builder = StringBuffer();
    for (final rune in text.runes) {
      if (_IsIgnorable(rune)) {
        continue;
      }
      if (rune == 0x69 && _turkicCasing) {
        // i: its upper case is İ (U+0130) in Turkish.
        builder.writeCharCode(0x130);
      } else if (rune == 0x131) {
        // ı (dotless i): I in Turkish; elsewhere a letter of its own, not i.
        builder.writeCharCode(_turkicCasing ? 0x49 : 0x131);
      } else {
        builder.write(String.fromCharCode(rune).toUpperCase());
      }
    }
    return builder.toString();
  }

  static String _RemoveIgnorable(String text) =>
      String.fromCharCodes(text.runes.where((rune) => !_IsIgnorable(rune)));

  /// Whether the collation ignores the code point (soft hyphen, zero-width and bidi controls, BOM, ...).
  static bool _IsIgnorable(int rune) =>
      rune == 0xAD ||
      (rune >= 0x200B && rune <= 0x200F) ||
      (rune >= 0x202A && rune <= 0x202E) ||
      (rune >= 0x2060 && rune <= 0x2064) ||
      rune == 0xFEFF ||
      rune == 0x61C;
}

/// Equivalent of System.Globalization.CultureInfo (only what NodaTime uses); immutable.
final class NodaCultureInfo implements IFormatProvider {
  /// The culture name, e.g. "fr-FR"; "" for the invariant culture.
  final String Name;
  final DateTimeFormatInfo DateTimeFormat;
  final nt.CompareInfo CompareInfo;
  final Map<String, String> _patternResourceOverrides;

  NodaCultureInfo._NewData(CultureData data)
      : Name = data.Name,
        DateTimeFormat = DateTimeFormatInfo(data.DateTimeFormat),
        CompareInfo = nt.CompareInfo.NewName(data.Name),
        _patternResourceOverrides = data.PatternResources ?? const {};

  /// Creates a culture from exported (or hand-modified) data.
  static NodaCultureInfo FromData(CultureData data) => NodaCultureInfo._NewData(data);

  /// Creates a culture from exported data and registers it for [CurrentCulture].
  @internal
  static NodaCultureInfo FromDataRegistered(CultureData data) {
    final culture = NodaCultureInfo._NewData(data);
    Register([culture]);
    return culture;
  }

  /// Equivalent of CultureInfo.InvariantCulture.
  static final NodaCultureInfo InvariantCulture = NodaCultureInfo._NewData(invariantCultureData);

  // The cultures registered for CurrentCulture, by lower-case name, in registration order.
  static final Map<String, NodaCultureInfo> _registeredCultures = <String, NodaCultureInfo>{};

  /// Makes cultures available to [CurrentCulture] before first use; replaces a culture of the same name.
  static void Register(Iterable<NodaCultureInfo> cultures) {
    for (final culture in cultures) {
      // The invariant culture isn't a host language's culture.
      if (culture.Name != '') {
        _registeredCultures[culture.Name.toLowerCase()] = culture;
      }
    }
  }

  /// The registered culture best matching the host's languages (CultureInfo.CurrentCulture): same name ("es-AR"),
  /// else the language ("es"), else that language's first registered culture.
  ///
  /// Throws [StateError] if none matches.
  static NodaCultureInfo get CurrentCulture {
    final languages = HostLanguages();
    for (final language in languages) {
      final culture = _MatchRegisteredCulture(language);
      if (culture != null) {
        return culture;
      }
    }
    final registered = [for (final culture in _registeredCultures.values) culture.Name];
    throw StateError(
        '${languages.isEmpty ? 'The host reports no languages' : "None of the host's languages (${languages.join(', ')})"} '
        'matches a registered culture (${registered.isEmpty ? 'none are registered' : registered.join(', ')}). '
        'Register the cultures you support with NodaCultureInfo.Register.');
  }

  /// Cultures are always read-only in noda_dart.
  bool get IsReadOnly => true;

  /// Equivalent of PatternResources.ResourceManager.GetString(name, culture).
  String? GetPatternResource(String name) => _patternResourceOverrides[name] ?? PatternResources[name];

  @override
  String toString() => Name;

  /// The registered culture for a language tag: same name, else the language alone, else that language's first.
  static NodaCultureInfo? _MatchRegisteredCulture(String tag) {
    final name = tag.toLowerCase();
    final exact = _registeredCultures[name];
    if (exact != null) {
      return exact;
    }
    final language = name.split('-').first;
    final neutral = _registeredCultures[language];
    if (neutral != null) {
      return neutral;
    }
    for (final entry in _registeredCultures.entries) {
      if (entry.key.split('-').first == language) {
        return entry.value;
      }
    }
    return null;
  }
}
